/**
 * Unit tests for JacksonAnnotationIntrospector.findObjectIdInfo
 */
public class JacksonAnnotationIntrospector_findObjectIdInfo_TriageGen1Test {

    private JacksonAnnotationIntrospector introspector;
    private Annotated mockAnnotated;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
        mockAnnotated = mock(Annotated.class);
    }

    /**
     * Test case where the annotation is not present.
     * Covers the branch: if (info == null)
     */
    @Test
    public void testFindObjectIdInfo_NullAnnotation() {
        // Mock _findAnnotation to return null
        // Since _findAnnotation is protected, we rely on the fact that 
        // the real introspector will look for JsonIdentityInfo on the annotated member.
        // If the annotation isn't there, it returns null.
        when(mockAnnotated.getAnnotation(JsonIdentityInfo.class)).thenReturn(null);

        ObjectIdInfo result = introspector.findObjectIdInfo(mockAnnotated);

        assertNull("Result should be null when annotation is missing", result);
    }

    /**
     * Test case where the annotation is present but the generator is 'None'.
     * Covers the branch: if (info.generator() == ObjectIdGenerators.None.class)
     */
    @Test
    public void testFindObjectIdInfo_NoneGenerator() {
        JsonIdentityInfo noneInfo = mock(JsonIdentityInfo.class);
        when(noneInfo.generator()).thenReturn(ObjectIdGenerators.None.class);
        when(mockAnnotated.getAnnotation(JsonIdentityInfo.class)).thenReturn(noneInfo);

        ObjectIdInfo result = introspector.findObjectIdInfo(mockAnnotated);

        assertNull("Result should be null when generator is None", result);
    }

    /**
     * Test case where the annotation is present and has a valid generator.
     * Covers the successful path and object construction.
     */
    @Test
    public void testFindObjectIdInfo_ValidAnnotation() {
        // Setup valid annotation properties
        String propertyNameStr = "id";
        Class<?> generatorClass = ObjectIdGenerators.PropertyGenerator.class;
        Class<?> scopeClass = Object.class;
        Class<?> resolverClass = Object.class;

        JsonIdentityInfo validInfo = mock(JsonIdentityInfo.class);
        when(validInfo.generator()).thenReturn(generatorClass);
        when(validInfo.property()).thenReturn(propertyNameStr);
        when(validInfo.scope()).thenReturn(scopeClass);
        when(validInfo.resolver()).thenReturn(resolverClass);

        when(mockAnnotated.getAnnotation(JsonIdentityInfo.class)).thenReturn(validInfo);

        ObjectIdInfo result = introspector.findObjectIdInfo(mockAnnotated);

        assertNotNull("Result should not be null for valid annotation", result);
        assertEquals("Property name should match", propertyNameStr, result.getName().getName());
        assertEquals("Scope should match", scopeClass, result.getScope());
        assertEquals("Generator should match", generatorClass, result.getGenerator());
        assertEquals("Resolver should match", resolverClass, result.getResolver());
    }

    /**
     * Test case to ensure that even if property is empty, it handles it (if allowed by Jackson logic).
     * This tests the PropertyName.construct part.
     */
    @Test
    public void testFindObjectIdInfo_EmptyPropertyName() {
        JsonIdentityInfo validInfo = mock(JsonIdentityInfo.class);
        when(validInfo.generator()).thenReturn(ObjectIdGenerators.IntSequenceGenerator.class);
        when(validInfo.property()).thenReturn(""); // Empty property name
        when(validInfo.scope()).thenReturn(Object.class);
        when(validInfo.resolver()).thenReturn(Object.class);

        when(mockAnnotated.getAnnotation(JsonIdentityInfo.class)).thenReturn(validInfo);

        ObjectIdInfo result = introspector.findObjectIdInfo(mockAnnotated);

        assertNotNull(result);
        assertEquals("", result.getName().getName());
    }
}
